      let authEnd = str.indexOf('/', 2)
      let queryStart = str.indexOf('?', 2)
      let fragmentStart = str.indexOf('#', 2)

      let endIdx = -1
      if (authEnd === -1) endIdx = queryStart
      else if (queryStart === -1) endIdx = authEnd
      else endIdx = Math.min(authEnd, queryStart)

      if (fragmentStart !== -1 && (endIdx === -1 || fragmentStart < endIdx)) {
        endIdx = fragmentStart
      }

      if (endIdx === -1) {
        authority = str.substring(2)
        i = str.length
      } else {
        authority = str.substring(2, endIdx)
        i = endIdx
      }
    }

    str = str.substring(i)
    i = 0

    // Parse path: runs to next '?' or '#'
    let pathEnd = str.indexOf('?')
    let fragmentStart = str.indexOf('#')
    if (pathEnd === -1) pathEnd = fragmentStart
    else if (fragmentStart !== -1 && fragmentStart < pathEnd) pathEnd = fragmentStart

    if (pathEnd === -1) {
      path = str
      i = str.length
    } else {
      path = str.substring(0, pathEnd)
      i = pathEnd
    }

    str = str.substring(i)
    i = 0

    // Parse query: optional, from '?' to next '#'
    if (str.startsWith('?')) {
      fragmentStart = str.indexOf('#', 1)
      if (fragmentStart === -1) {
        query = str.substring(1)
        i = str.length
      } else {
        query = str.substring(1, fragmentStart)
        i = fragmentStart
      }
    }

    str = str.substring(i)

    // Parse fragment: optional, from '#' to end
    if (str.startsWith('#')) {
      fragment = str.substring(1)
    }

    return new URI(scheme, authority, path, query, fragment)
  }

  toString() {
    let result = ''
    if (this.scheme !== null) result += this.scheme + ':'
    if (this.authority !== null) result += '//' + this.authority
    result += this.path
    if (this.query !== null) result += '?' + this.query
    if (this.fragment !== null) result += '#' + this.fragment
    return result
  }
