// ============================================================================
// Percent Encoding Utilities
// ============================================================================

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function hexToInt(hex) {
  return parseInt(hex, 16)
}

function isUnreserved(c) {
  return (
    (c >= 'A' && c <= 'Z') ||
    (c >= 'a' && c <= 'z') ||
    (c >= '0' && c <= '9') ||
    c === '-' ||
    c === '.' ||
    c === '_' ||
    c === '~'
  )
}

function normalizePercentEncoding(component) {
  if (component === null) return null

  let result = ''
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        return null // Truncated percent-encoding
      }
      const hex1 = component[i + 1]
      const hex2 = component[i + 2]
      if (!isHexDigit(hex1) || !isHexDigit(hex2)) {
        return null // Invalid hex digits
      }
      const charCode = hexToInt(hex1 + hex2)
      const char = String.fromCharCode(charCode)
      if (isUnreserved(char)) {
        result += char
      } else {
        result += '%' + hex1.toUpperCase() + hex2.toUpperCase()
      }
      i += 2
    } else {
      result += component[i]
    }
  }
  return result
}

// ============================================================================
// Authority Parsing
// ============================================================================

function parseAuthority(authority) {
  let userinfo = ''
  let host = authority
  let port = null

  // Find last '@' to separate userinfo and host+port
  const lastAtIdx = authority.lastIndexOf('@')
  if (lastAtIdx !== -1) {
    userinfo = authority.substring(0, lastAtIdx)
    host = authority.substring(lastAtIdx + 1)
  }

  // Find port: everything after first ':' that follows last ']'
  const lastBracketIdx = host.lastIndexOf(']')
  let colonIdx = -1
  if (lastBracketIdx !== -1) {
    colonIdx = host.indexOf(':', lastBracketIdx)
  } else {
    colonIdx = host.indexOf(':')
  }

  if (colonIdx !== -1) {
    port = host.substring(colonIdx + 1)
    host = host.substring(0, colonIdx)
  }

  return { userinfo, host, port }
}

function serializeAuthority(userinfo, host, port) {
  let result = ''
  if (userinfo) result += userinfo + '@'
  result += host
  if (port) result += ':' + port
  return result
