// ============================================================================
// Normalization
// ============================================================================

function normalizeSchemeLowercase(scheme) {
  if (scheme === null) return null
  let result = ''
  for (let i = 0; i < scheme.length; i++) {
    const c = scheme[i]
    if (c >= 'A' && c <= 'Z') {
      result += String.fromCharCode(c.charCodeAt(0) + 32)
    } else {
      result += c
    }
  }
  return result
}

function normalizeHostLowercase(host) {
  let result = ''
  for (let i = 0; i < host.length; i++) {
    const c = host[i]
    if (c >= 'A' && c <= 'Z') {
      result += String.fromCharCode(c.charCodeAt(0) + 32)
    } else {
      result += c
    }
  }
  return result
}

function removeDotSegments(path) {
  // RFC 3986 section 5.2.4
  let inputBuffer = path
  let outputBuffer = ''

  while (inputBuffer.length > 0) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (inputBuffer.startsWith('../')) {
      inputBuffer = inputBuffer.substring(3)
    } else if (inputBuffer.startsWith('./')) {
      inputBuffer = inputBuffer.substring(2)
    }
    // B: If the input buffer begins with a prefix of "/./"
    else if (inputBuffer.startsWith('/./')) {
      inputBuffer = '/' + inputBuffer.substring(3)
    }
    // B: If the input buffer is exactly "/."
    else if (inputBuffer === '/.') {
      inputBuffer = '/'
    }
    // C: If the input buffer begins with a prefix of "/../"
    else if (inputBuffer.startsWith('/../')) {
      inputBuffer = '/' + inputBuffer.substring(4)
      // Remove the last segment from output
      const lastSlashIdx = outputBuffer.lastIndexOf('/')
      if (lastSlashIdx !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlashIdx)
      }
    }
    // C: If the input buffer is exactly "/.."
    else if (inputBuffer === '/..') {
      inputBuffer = '/'
      // Remove the last segment from output
      const lastSlashIdx = outputBuffer.lastIndexOf('/')
      if (lastSlashIdx !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlashIdx)
      }
    }
    // D: If the input buffer is exactly "." or ".."
    else if (inputBuffer === '.' || inputBuffer === '..') {
      inputBuffer = ''
    }
    // E: move the first path segment to output
    else {
      let segmentEnd
      if (inputBuffer.startsWith('/')) {
        segmentEnd = inputBuffer.indexOf('/', 1)
        if (segmentEnd === -1) segmentEnd = inputBuffer.length
      } else {
        segmentEnd = inputBuffer.indexOf('/')
        if (segmentEnd === -1) segmentEnd = inputBuffer.length
      }
      outputBuffer += inputBuffer.substring(0, segmentEnd)
      inputBuffer = inputBuffer.substring(segmentEnd)
    }
  }

  return outputBuffer
}

function normalizeURI(uri) {
  const normalized = new URI()

  // 1. Lowercase the scheme
  normalized.scheme = normalizeSchemeLowercase(uri.scheme)

  // 2. Normalize percent-encodings in userinfo (if authority exists)
  let authority = uri.authority
  if (authority !== null) {
    const auth = parseAuthority(authority)

    // Normalize percent-encodings in userinfo
    const normalizedUserinfo = normalizePercentEncoding(auth.userinfo)
    if (normalizedUserinfo === null) {
      return { error: 'userinfo' }
    }

    // Normalize percent-encodings in host
    const normalizedHost = normalizePercentEncoding(auth.host)
    if (normalizedHost === null) {
      return { error: 'host' }
    }

    // 3. Lowercase the host
    const lowercaseHost = normalizeHostLowercase(normalizedHost)

    // 4. Drop default port
    let port = auth.port
    if (port !== null && port !== '') {
      const defaultPorts = {
        'http': '80',
        'https': '443',
        'ws': '80',
        'wss': '443',
        'ftp': '21'
      }
      if (normalized.scheme && defaultPorts[normalized.scheme] === port) {
        port = null
      }
    } else if (port === '') {
      port = null
    }

    normalized.authority = serializeAuthority(normalizedUserinfo, lowercaseHost, port)
  }

  // Normalize percent-encodings in path
  const normalizedPath = normalizePercentEncoding(uri.path)
  if (normalizedPath === null) {
    return { error: 'path' }
  }

  // Remove dot segments from path
  const cleanedPath = removeDotSegments(normalizedPath)

  // If authority is present and path is empty, make it '/'
  if (normalized.authority !== null && cleanedPath === '') {
    normalized.path = '/'
  } else {
    normalized.path = cleanedPath
  }

  // Normalize percent-encodings in query
  const normalizedQuery = normalizePercentEncoding(uri.query)
  if (normalizedQuery === null) {
    return { error: 'query' }
  }
  normalized.query = normalizedQuery

  // Normalize percent-encodings in fragment
  const normalizedFragment = normalizePercentEncoding(uri.fragment)
  if (normalizedFragment === null) {
    return { error: 'fragment' }
  }
  normalized.fragment = normalizedFragment

  return normalized
