// Resolution
// ============================================================================

function resolveURI(base, ref) {
  // RFC 3986 section 5.2.2
  const target = new URI()

  if (ref.scheme !== null) {
    // Reference has a scheme: it's the target
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    if (ref.authority !== null) {
      // Reference has authority
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      if (ref.path === '') {
        // Reference has empty path
        target.path = base.path
        if (ref.query !== null) {
          target.query = ref.query
        } else {
          target.query = base.query
        }
      } else {
        if (ref.path.startsWith('/')) {
          // Reference path is absolute
          target.path = removeDotSegments(ref.path)
        } else {
          // Merge paths
          if (base.authority !== null && base.path === '') {
            target.path = '/' + ref.path
          } else {
            const lastSlashIdx = base.path.lastIndexOf('/')
            if (lastSlashIdx !== -1) {
              target.path = base.path.substring(0, lastSlashIdx + 1) + ref.path
            } else {
              target.path = ref.path
            }
          }
          target.path = removeDotSegments(target.path)
        }
        target.query = ref.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }

  target.fragment = ref.fragment

  return target
}

// ============================================================================
// Main
// ============================================================================

const args = process.argv.slice(2)

if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  // Handle error reading stdin
}

// Split into lines, dropping empty tail from trailing newline
const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

let hasError = false

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
  const line = lines[lineNum]
  const recordNum = lineNum + 1

  try {
    if (mode === 'normalize') {
      const uri = URI.parse(line)
      const normalized = normalizeURI(uri)
      if (normalized.error) {
        process.stderr.write(`error: line ${recordNum}: the ${normalized.error} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      console.log(normalized.toString())
    } else {
      // resolve mode
      const spaceIdx = line.indexOf(' ')
      if (spaceIdx === -1) {
        process.stderr.write(`error: line ${recordNum}: expected a base and a reference\n`)
        process.exit(2)
      }

      const baseStr = line.substring(0, spaceIdx)
      const refStr = line.substring(spaceIdx + 1)

      const base = URI.parse(baseStr)
      if (base.scheme === null) {
        process.stderr.write(`error: line ${recordNum}: the base has no scheme\n`)
        process.exit(2)
      }

      const ref = URI.parse(refStr)

      // Check for truncated percent-encodings in reference components
      let refNormError = null
      for (const component of ['scheme', 'authority', 'path', 'query', 'fragment']) {
        if (component === 'scheme' || component === 'authority') {
          // These are checked as part of resolution
          continue
        }
        const result = normalizePercentEncoding(ref[component])
        if (result === null) {
          refNormError = component
          break
        }
      }

      if (refNormError) {
        process.stderr.write(`error: line ${recordNum}: the ${refNormError} has a truncated percent-encoding\n`)
        process.exit(2)
      }

      const resolved = resolveURI(base, ref)
      const normalized = normalizeURI(resolved)
      if (normalized.error) {
        process.stderr.write(`error: line ${recordNum}: the ${normalized.error} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      console.log(normalized.toString())
    }
  } catch (e) {
    process.stderr.write(`error: line ${recordNum}: ${e.message}\n`)
    process.exit(2)
  }
}

process.exit(0)
